// Generated by `cargo xt gen` from the app's event types (app/src-tauri src/events.rs) through gmclip-core's src/tsgen.rs. Do not edit: change the Rust types and run it again.
// app/src-tauri tests/ts_events.rs fails while this file and the types disagree.

/** The `agents` scope: agent sessions (decision 0035). */
export type AgentsEvent = {
  kind: "resync";
} | {
  kind: "session";
  session: SessionView;
} | {
  entry: Entry;
  index: number;
  kind: "entry";
  session: string;
} | {
  index: number;
  kind: "append";
  session: string;
  text: string;
} | {
  kind: "removed";
  session: string;
};

/** Where one source's analysis is (the `analysis` event). */
export type AnalysisProgress = {
  asr_error?: string | null;
  done_s: number;
  error?: string | null;
  job?: string | null;
  paused: boolean;
  pauses: number;
  /** `transcribing`, `analysing`, `done`, `failed`. */
  phase: string;
  resumed_at_s?: number | null;
  source: string;
  total_s: number;
  /** Words heard so far. */
  words: number;
};

/** The `app` scope: the native menu and the speech model download. */
export type AppEvent = {
  kind: "resync";
} | {
  id: string;
  kind: "menu";
} | ({
  done?: number | null;
  error?: string | null;
  file?: string | null;
  kind: "models";
  state: ModelsState;
  total?: number | null;
});

/** What the audio side reports (the A/V offset is the shown frame's centre minus the sample being heard when it was handed to the frame socket). */
export type AudioStats = {
  av_frames: number;
  av_max_ms: number;
  av_mean_ms: number;
  device: boolean;
  latency_ms: number;
  muted: boolean;
  /** Why this plan plays no sound (its audio would not build), when it plays none. */
  no_sound?: string | null;
  /** Output device switches the engine recovered from (it reopens on the new device; the A/V numbers above restart there, measured against the new device's latency). */
  reopens: number;
  underruns: number;
};

export type BatchCut = {
  cut: string;
  reason?: string | null;
  run?: string | null;
  /** `queued`, `running`, `done`, `failed`, `skipped` (edited after the start), `stopped` (the wall clock ran out mid-run) or `not_run` (never reached). */
  state: string;
  title: string;
};

export type BatchView = {
  /** What the batch may spend on metered AI (`0`: the person's own plan). */
  budget_usd: number;
  cuts: BatchCut[];
  /** The agent each cut runs with (decision 0012). */
  harness?: string | null;
  id: string;
  pass: string;
  /** One cut's run at most. */
  per_cut_s: number;
  preapproval: PreApproval;
  project: string;
  started_ms: number;
  /** `running`, `done`, or `stopped` (its wall clock ran out before every cut ran). */
  state: string;
  wall_clock_s: number;
};

/** A file a tool call changes. */
export type DiffView = {
  added: number;
  path: string;
  removed: number;
};

/** The tool a session is running. */
export type Doing = {
  gmclip: boolean;
  kind: string;
  title: string;
};

/** One line of a session's transcript. */
export type Entry = {
  ms: number;
  text: string;
  type: "user";
} | {
  text: string;
  type: "agent";
} | {
  text: string;
  type: "thought";
} | ({
  detail?: string | null;
  diffs: DiffView[];
  /** One of gmclip's own tools. */
  gmclip: boolean;
  id: string;
  /** The call's input, compact (untrusted). */
  input?: string | null;
  kind: string;
  locations: string[];
  status: string;
  title: string;
  type: "tool";
}) | {
  items: PlanItem[];
  type: "plan";
} | ({
  /** The option picked (`cancelled` when the turn ended first). */
  chosen?: string | null;
  id: string;
  kind?: string | null;
  options: PermOption[];
  title: string;
  type: "permission";
}) | {
  error: boolean;
  text: string;
  type: "notice";
};

/** One change in an event: the entity, and the field (and map key) for a field op. */
export type EventTriple = {
  entity: string;
  field?: string | null;
  key?: string | null;
  /** `set`, `create` or `delete`. */
  op: string;
};

/** The `home` scope: what Home lists changed. */
export type HomeEvent = {
  kind: "resync";
} | {
  kind: "changed";
} | ({
  at?: number[] | null;
  kind: "dropped";
  paths: string[];
}) | {
  exe: string;
  identity: string;
  kind: "first_seen";
  ts: number;
} | ({
  cut?: string | null;
  kind: "needs_you";
});

/** One export job as the UI sees it. */
export type JobView = {
  cut: string;
  done: number;
  error?: string | null;
  export?: string | null;
  finished_ms?: number | null;
  frames: number;
  id: string;
  kind: string;
  /** `captions` (hearing the parts whose audio changed, SPEC §5.10), `audio` (mix, loudness, AAC: before the first video frame) or `video`. */
  phase: "captions" | "audio" | "video";
  project: string;
  started_ms: number;
  state: string;
  title: string;
};

/** The `jobs` scope: exports. */
export type JobsEvent = {
  kind: "resync";
} | {
  job: JobView;
  kind: "job";
};

/** A mode the agent offers (Claude Code: Ask, Accept edits, Plan, …). */
export type ModeView = {
  id: string;
  name: string;
};

export type ModelsState = "running" | "paused" | "done" | "failed";

/** One answer a permission request offers. */
export type PermOption = {
  id: string;
  /** `allow_once`, `allow_always`, `reject_once`, `reject_always`. */
  kind: string;
  name: string;
};

/** One step of the agent's plan. */
export type PlanItem = {
  content: string;
  priority: string;
  status: string;
};

/** The pre-approval a batch records at launch (§10.7.1): AI passes within the budget need no further approval while it runs; anything over the budget still does. */
export type PreApproval = {
  budget_usd: number;
  by: string;
  covers: string[];
  recorded_ms: number;
};

/** The `project:<id>` scope: the core's committed transactions, and the app's own news about the project (analysis, agent runs, batches, clips, proxies, review-link writes). */
export type ProjectEvent = {
  by: string;
  command: string;
  display: string;
  kind: "committed";
  rev: number;
  seq: number;
  triples: EventTriple[];
} | ({
  kind: "resync";
  rev?: number | null;
  seq?: number | null;
}) | {
  kind: "changed";
} | {
  kind: "sources";
} | (AnalysisProgress & {
  kind: "analysis";
}) | {
  kind: "transcript";
  source: string;
} | {
  kind: "agent_run";
  run: RunView;
} | {
  batch: BatchView;
  kind: "batch";
} | ({
  error?: string | null;
  kind: "clip";
  moment: string;
  picture?: string | null;
  ready: boolean;
  render_ms?: number | null;
}) | {
  covered: number;
  frames: number;
  kind: "proxy";
  phase: string;
  project: string;
  source: string;
} | {
  cut: string;
  kind: "review";
} | ({
  cut?: string | null;
  kind: "comments";
}) | {
  cut: string;
  export: string;
  kind: "export_verify";
} | {
  cut: string;
  kind: "output";
};

/** One run as the UI shows it. */
export type RunView = {
  /** The build failed the isolation check: `{version, sha256, failed: [{id, what, …}]}` ("Run anyway" needs the Owner sheet). */
  blocked?: unknown;
  /** G.03: the app run this continues, and whether it resumed the client's session. */
  continued_from?: string | null;
  cut: string;
  ended_ms?: number | null;
  error?: string | null;
  exit_code?: number | null;
  /** What it produced (find moments: moments added). */
  found?: number | null;
  harness: string;
  harness_label: string;
  id: string;
  /** G.04: the latest see / listen / transcript_read of a live run. */
  looking_at?: unknown;
  pass: string;
  project: string;
  resumed: boolean;
  /** "Continue" would resume this run's own session (pi, opencode with a session id). */
  resumes: boolean;
  started_ms: number;
  /** `starting`, `checking` (a new Claude Code build gets the one-time isolation check), `running`, `done`, `failed`. */
  state: string;
  summary?: string | null;
  tool_calls?: number | null;
};

/** One session as the UI lists it. */
export type SessionView = {
  access: "gmclip" | "full" | "bypass";
  /** The agent's own name and version, as it said (untrusted). */
  agent?: string | null;
  /** The core's runs this session wrote in (cut sessions): what "Undo run" undoes. */
  core_runs?: string[];
  cwd?: string | null;
  /** The tool it is running now. */
  doing?: Doing | null;
  entries: number;
  error?: string | null;
  harness: string;
  harness_label: string;
  id: string;
  /** The identity gmclip's tools see. */
  identity?: string | null;
  last_ms: number;
  media: boolean;
  mode?: string | null;
  model?: string | null;
  /** The models the agent offers for this session (`id`, `name`), when it says. */
  models?: ModeView[];
  modes: ModeView[];
  /** The agent said it can load or resume this session after it ends (`session_resume` asks it again: sessions kept from before resume was supported say false). */
  resumable: boolean;
  /** The holder's launched run (cut sessions): what "Undo run" undoes. */
  run?: string | null;
  started_ms: number;
  /** `waiting`: a permission request waits for the human. */
  state: "starting" | "working" | "waiting" | "idle" | "ended" | "failed";
  stop_reason?: string | null;
  target: Target;
  /** The first message's first line (or the title the agent gave). */
  title: string;
  tool_calls: number;
  /** How it speaks ACP ("claude-code-acp", "npx @zed-industries/codex-acp"). */
  via?: string | null;
  /** The cuts its gmclip tools read or changed, in first-touched order (what the workspace draws instead of the log). */
  work?: WorkItem[];
};

/** What a session works on. */
export type Target = {
  cut?: string | null;
  /** `library`, `project`, `video`, `cut`. */
  kind: "library" | "project" | "video" | "cut";
  /** "cut “Hook test” · Stream 14", "video stream.mp4 · Stream 14", "Library". */
  label: string;
  project?: string | null;
  project_name?: string | null;
  /** The video (a source of the project). */
  source?: string | null;
};

/** The `viewer` scope: the render thread's state and errors. */
export type ViewerEvent = {
  kind: "resync";
} | {
  kind: "state";
  state: ViewerState;
} | ({
  cut?: string | null;
  error?: string | null;
  kind: "error";
}) | ({
  cut: string;
  kind: "mattes";
  project: string;
  state?: string | null;
});

/** What the viewer shows and does, for `gm_call viewer_state` and the `viewer` scope. */
export type ViewerState = {
  /** Playback audio: device latency, A/V offset at frame handoff, underruns, muted. */
  audio: AudioStats;
  cut?: string | null;
  /** The last frame drew a live draft matte (no accurate mask track yet): the viewer's "draft matte" badge (SPEC §5.8). */
  draft_matte: boolean;
  /** The layer being dragged, `[x, y, w, h]` canvas px, while a drag is on (the UI draws its off-canvas ghost: what lies past the frame's edge). */
  drag?: [number, number, number, number] | null;
  dropped: number;
  error?: string | null;
  /** Frames per second (29.97… at an NTSC rate). */
  fps: number;
  frame: number;
  frames: number;
  /** The framing shown when it is not the cut's own (the crop editor). */
  framing?: string | null;
  full: boolean;
  /** Snap guides of the drag: `(vertical, at)` in canvas px. */
  guides: Array<[boolean, number]>;
  /** Matte view: matted layers' masks in white on black (R.02). */
  matte_view: boolean;
  playing: boolean;
  project?: string | null;
  /** Playback speed (J/K/L shuttle): 1.0 normal; negative while J plays backwards (silent, on the scrub path; the exact frame shows once it stops). */
  rate: number;
  rendered: number;
  /** Scrub audio on (a grain at each step or seek while paused). */
  scrub: boolean;
  /** Where the last frame's pictures came from: `exact` (the master), `proxy` (the scrub proxy) or `keyframe` (the master's keyframe; the proxy does not cover the frame yet). Scrub frames settle to `exact` 150 ms after the last scrub step. */
  scrub_path: "exact" | "proxy" | "keyframe" | null;
  /** `(plan part id, plan layer id)` of the selected layer. */
  selected?: [string, string] | null;
  size: [number, number];
  /** A text overlay or the caption seat being dragged (U.12): how far the frame draws it from where the cut has it, `(dx, dy)` canvas px, until the commit's re-planned cut arrives (then the frame is the plan's own again). */
  text_drag?: [number, number] | null;
};

/** One cut a session touched. */
export type WorkItem = {
  calls: number;
  /** The session made this cut. */
  created: boolean;
  cut: string;
  first_ms: number;
  last_ms: number;
  /** Its last gmclip tool on this cut (`cut_trim`, `part_delete`, …). */
  last_tool: string;
  parts: number;
  /** Parts when the session first touched it (or made it). */
  parts_before: number;
  project: string;
  title: string;
};

/** Each `gm_subscribe` scope's events (`project` is every `project:<id>`). */
export interface Scopes {
  viewer: ViewerEvent;
  jobs: JobsEvent;
  app: AppEvent;
  home: HomeEvent;
  agents: AgentsEvent;
  project: ProjectEvent;
}
